xql_query:
// ============================================================
// Rule: THM_Disable Windows Recovery Environment
// Vendor: Windows
// Objective:
// Detect activity associated with THM_Disable Windows Recovery Environment.
// Severity: SEV_040_HIGH
// Category: TAMPERING
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1562.001 - Impair Defenses: Disable or Modify Tools

// Configuração inicial: define que as comparações de strings não diferenciam maiúsculas/minúsculas
config case_sensitive = false  

// Fonte de dados: eventos coletados pelo Cortex XDR
| dataset = xdr_data  

// Filtro para selecionar apenas eventos do tipo PROCESS
| filter event_type = ENUM.PROCESS  

// Seleção dos campos mais relevantes para análise do processo
| fields _time,                          // Data e hora do evento
         agent_hostname,                 // Host onde ocorreu a execução
         actor_process_image_name,       // Processo que originou a execução
         action_process_image_name,      // Nome do processo em execução
         action_process_image_command_line // Linha de comando do processo executado

// Filtro adicional: detecção da execução do processo reagentc.exe
// com o parâmetro "/disable"
// - reagentc.exe é utilizado para gerenciar a recuperação do Windows
// - a flag "/disable" pode indicar tentativa de desativar a recuperação do sistema
| filter action_process_image_name = "reagentc.exe"
        and lowercase(action_process_image_command_line) contains "/disable"
